            // Regulars
            { "regular.0.name", new[] { "Боб", "Bob" } },
            { "regular.0.about", new[] { "дальнобойщик, любит дизель и кофе", "trucker, loves diesel and coffee" } },
            { "regular.0.line.0", new[] { "Как обычно, дизель до полного. И кофе покрепче!", "The usual: diesel, fill her up. And strong coffee!" } },
            { "regular.0.line.1", new[] { "Семьсот миль позади, триста впереди. Жизнь!", "Seven hundred miles behind, three hundred ahead. That's life!" } },
            { "regular.1.name", new[] { "Марина", "Marina" } },
            { "regular.1.about", new[] { "таксистка, заезжает почти каждый день", "taxi driver, drops in almost every day" } },
            { "regular.1.line.0", new[] { "Быстренько, у меня клиент в аэропорт!", "Quick one, I've got a fare to the airport!" } },
            { "regular.1.line.1", new[] { "Опять весь город перекопали, только у вас спокойно.", "They dug up the whole town again, only here it's quiet." } },
            { "regular.2.name", new[] { "Семья Ивановых", "The Ivanov family" } },
            { "regular.2.about", new[] { "едут на выходные к морю", "driving to the seaside for the weekend" } },
            { "regular.2.line.0", new[] { "Дети, в туалет и обратно, быстро!", "Kids, restroom and back, quick!" } },
            { "regular.2.line.1", new[] { "Помоем машину — и дальше, отпуск ждёт!", "A car wash and we're off, the holiday awaits!" } },
            { "regular.3.name", new[] { "Байкер Гарри", "Harry the biker" } },
            { "regular.3.about", new[] { "гоняет по пятницам и субботам", "rides on Fridays and Saturdays" } },
            { "regular.3.line.0", new[] { "Полный бак девяносто пятого для моей красотки.", "Fill up my beauty with 95." } },
            { "regular.3.line.1", new[] { "Слышал про слёт в пустыне? Будет громко!", "Heard about the desert rally? It's going to be loud!" } },
            { "regular.4.name", new[] { "Дед Петя", "Old Pete" } },
            { "regular.4.about", new[] { "пенсионер, заезжает за газетой и кофе", "retiree, comes for the paper and coffee" } },
            { "regular.4.line.0", new[] { "Раньше тут бензин стоил копейки, эх...", "Gas used to cost pennies here, oh well..." } },
            { "regular.4.line.1", new[] { "Кофе у вас лучше, чем в городе, честно.", "Your coffee beats the town's, honest." } },
            { "regular.5.name", new[] { "Лена", "Lena" } },
            { "regular.5.about", new[] { "курьер, всегда торопится", "courier, always in a hurry" } },
            { "regular.5.line.0", new[] { "У меня восемь посылок и полчаса!", "Eight parcels and half an hour!" } },
            { "regular.5.line.1", new[] { "Только не очередь, только не сегодня...", "Not a queue, not today..." } },
            { "regular.6.name", new[] { "Большой Майк", "Big Mike" } },
            { "regular.6.about", new[] { "ночной дальнобойщик", "night trucker" } },
            { "regular.6.line.0", new[] { "Ночью на трассе только я да койоты.", "At night it's just me and the coyotes out here." } },
            { "regular.6.line.1", new[] { "Дизель, пончик и десять минут тишины.", "Diesel, a donut and ten minutes of quiet." } },
            { "regular.7.name", new[] { "Доктор Картер", "Dr. Carter" } },
            { "regular.7.about", new[] { "врач, по утрам едет в больницу", "doctor, drives to the hospital in the mornings" } },
            { "regular.7.line.0", new[] { "Смена через сорок минут, выручайте.", "My shift starts in forty minutes, help me out." } },
            { "regular.7.line.1", new[] { "Чистый туалет на заправке — это медицина!", "A clean restroom is public health!" } },
            { "regular.8.name", new[] { "Шериф Доусон", "Sheriff Dawson" } },
            { "regular.8.about", new[] { "следит за порядком на трассе", "keeps the highway in order" } },
            { "regular.8.line.0", new[] { "Всё спокойно? Воров не видели?", "All quiet? Seen any thieves?" } },
            { "regular.8.line.1", new[] { "Хорошая заправка — меньше работы полиции.", "A good station means less work for the police." } },
            { "regular.9.name", new[] { "Фермер Роза", "Rosa the farmer" } },
            { "regular.9.about", new[] { "везёт урожай на рынок", "takes her crops to the market" } },
            { "regular.9.line.0", new[] { "Пикап полный арбузов, а бак пустой!", "The pickup's full of melons and the tank is empty!" } },
            { "regular.9.line.1", new[] { "Засуха в этом году, но мы держимся.", "Dry year, but we're hanging on." } },
            { "regular.10.name", new[] { "Коммивояжёр Тони", "Tony the salesman" } },
            { "regular.10.about", new[] { "продаёт пылесосы по всему штату", "sells vacuum cleaners all over the state" } },
            { "regular.10.line.0", new[] { "Кстати, пылесос вам не нужен? Шучу!", "Need a vacuum cleaner, by the way? Kidding!" } },
            { "regular.10.line.1", new[] { "Ещё три города до вечера. Кофе, пожалуйста!", "Three more towns before dark. Coffee, please!" } },
            { "regular.11.name", new[] { "Семья Ким", "The Kim family" } },
            { "regular.11.about", new[] { "воскресные путешественники", "Sunday travellers" } },
            { "regular.11.line.0", new[] { "Какие сувениры у вас есть?", "What souvenirs have you got?" } },
            { "regular.11.line.1", new[] { "Сфотографируемся у вашей вывески!", "Let's take a photo by your sign!" } },
            { "regular.12.name", new[] { "Студент Джейк", "Jake the student" } },
            { "regular.12.about", new[] { "едет домой на выходные", "drives home for the weekend" } },
            { "regular.12.line.0", new[] { "На десять долларов, больше нет...", "Ten dollars' worth, that's all I've got..." } },
            { "regular.12.line.1", new[] { "Чипсы и газировка — ужин чемпиона.", "Chips and soda, the dinner of champions." } },
            { "regular.13.name", new[] { "Бабушка Ольга", "Grandma Olga" } },
            { "regular.13.about", new[] { "едет к внукам по средам", "visits her grandchildren on Wednesdays" } },
            { "regular.13.line.0", new[] { "Внукам конфет возьму, у вас свежие?", "I'll get sweets for the grandkids, are they fresh?" } },
            { "regular.13.line.1", new[] { "Какой вежливый молодой человек!", "What a polite young man!" } },
