            { "letter.2.text", new[] { "«Банк доволен первым взносом. К двадцатому дню выплатите $20 000 в сумме. P. S. Сеть PetroMax интересуется вашей землёй.»", "\"The bank is pleased with the first payment. Have $20,000 paid in total by day twenty. P.S. The PetroMax chain is interested in your land.\"" } },
            { "letter.3.title", new[] { "Глава 3. Последний срок", "Chapter 3. The final deadline" } },
            { "letter.3.text", new[] { "«Остаток долга нужно погасить к тридцатому дню. Иначе станция перейдёт банку.»", "\"The rest of the debt must be paid by day thirty. Otherwise the station goes to the bank.\"" } },
            { "letter.offer.title", new[] { "PetroMax: купим вашу землю", "PetroMax: we'll buy your land" } },
            { "letter.offer.text", new[] { "«Предлагаем ${0:0} за участок. Долги — не ваша забота. Подпишите, и дело с концом.»", "\"We offer ${0:0} for the lot. The debts won't be your problem any more. Sign and it's over.\"" } },
            { "letter.offer.accept", new[] { "Продать за ${0:0}", "Sell for ${0:0}" } },
            { "letter.offer.decline", new[] { "Отказаться", "Decline" } },
            { "letter.end.Won", new[] { "Долг выплачен!", "The debt is paid!" } },
            { "letter.end.Won.text", new[] { "Станция твоя. Дядя бы гордился. Дальше — свободная игра.", "The station is yours. Your uncle would be proud. Free play from here on." } },
            { "letter.end.Lost", new[] { "Банк забрал станцию", "The bank took the station" } },
            { "letter.end.Lost.text", new[] { "Срок вышел.", "Time ran out." } },
            { "letter.end.Sold", new[] { "Земля продана", "The land is sold" } },
            { "letter.end.Sold.text", new[] { "PetroMax снесёт старую станцию.", "PetroMax will tear the old station down." } },
            { "letter.end.None", new[] { "Писем нет", "No letters" } },
            { "letter.end.None.text", new[] { "Новых писем нет.", "No new letters." } },
            { "menu.gameOver.campaign", new[] { "Станция ушла банку", "The bank took the station" } },
            { "menu.gameOver.campaign.text", new[] { "«{0}» не успела выплатить долг дяди: на {1}-й день банк забрал станцию.\nОбслужено клиентов: {2}. Уровень станции: {3}.", "\"{0}\" did not pay off the uncle's debt in time: on day {1} the bank took the station.\nCustomers served: {2}. Station level: {3}." } },
            { "menu.gameOver.sold", new[] { "Конец истории", "The end of the story" } },
            { "menu.gameOver.sold.text", new[] { "«{0}» продана сети PetroMax на {1}-й день. Деньги есть, станции нет.\nОбслужено клиентов: {2}. Уровень станции: {3}.", "You sold \"{0}\" to PetroMax on day {1}. You have the money, but not the station.\nCustomers served: {2}. Station level: {3}." } },
            { "menu.victory", new[] { "Наследство спасено!", "The inheritance is saved!" } },
            { "menu.victory.text", new[] { "«{0}» расплатилась с банком на {1}-й день.\nОбслужено клиентов: {2}. Звёзд у станции: {3}.\nДядя бы гордился. Станция твоя — играй дальше сколько захочешь.", "\"{0}\" paid off the bank on day {1}.\nCustomers served: {2}. Station stars: {3}.\nYour uncle would be proud. The station is yours — keep playing as long as you like." } },
            { "menu.victory.continue", new[] { "Играть дальше", "Keep playing" } },

            // Story quests for the newer systems
            { "quest.title.24", new[] { "Уют своими руками", "A cosy place" } },
